import {springCases,springCopy} from './spring-bench-content.mjs';
import {createSpring,springModel,changeSpring,springGeometry,springPlot,springExample} from './spring-bench-core.mjs';
import {stopSpeech} from './play-media.mjs';

const visits=new WeakMap();
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=x=>{try{return JSON.stringify(x);}catch{return null;}};
const routeOK=r=>typeof r==='string'&&(r==='#learn/science'||r.startsWith('#learn/science/'));
function visit(book,owner,create=false){
 if(!book||typeof book!=='object'||typeof owner!=='string'||!owner.trim())return null;
 let owners=visits.get(book);if(!owners&&create){owners=new Map();visits.set(book,owners);}
 let v=owners?.get(owner);if(!v&&create){v={cases:new Map(springCases.map(c=>[c.id,createSpring(c.id)])),id:'A',activeRoute:null,root:null,generation:0,screen:'trial',axis:'extension',reference:false,frame:0,caller:'trial',entry:null};owners.set(owner,v);}return v;
}
export function springBenchActive(book,owner,route=globalThis.location?.hash||''){return routeOK(route)&&visit(book,owner)?.activeRoute===route;}
const button=(action,label,disabled=false,primary=false)=>`<button type="button" data-sb-action="${action}"${disabled?' disabled':''}${primary?' class="sb-primary"':''}>${esc(label)}</button>`;
export function springBenchEntry(){return '<aside class="sb-entry"><button type="button" data-sb-entry>Spring Bench: length or extra length?</button></aside>';}

// An invalidated control remains retired even if the original appearance returns.
function bindingGuard(root,valid,stop=()=>{},nodes=[...root.querySelectorAll('button,input,select,a,details,summary')]){
 const controls=[root,...nodes].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.target.closest?.('.speech-controls,drawn-howto'))continue;if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const disconnect=()=>{disconnected=true;observer.disconnect();};
 const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});
 observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return node=>{audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||retired.has(node)||node.disabled)return false;const before=chains.get(node),now=chain(node);if(!before||before.length!==now.length||!before.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;};
}
export function bindSpringBenchEntry(book,ctx={}){
 const owner=ctx.explorerId?.(),route=location.hash,root=document.querySelector('[data-motion-root]'),node=root?.querySelector('[data-sb-entry]');if(!node||!routeOK(route))return;
 const v=visit(book,owner,true);if(!v)return;v.entry=node;
 const live=bindingGuard(root,()=>v.entry===node&&ctx.notebook?.()===book&&ctx.explorerId?.()===owner&&ctx.isActive?.()===true&&location.hash===route&&document.querySelector('[data-motion-root]')===root&&!springBenchActive(book,owner),()=>{},[node]);
 node.addEventListener('click',()=>{if(!live(node))return;try{if(ctx.canEnter?.()!==true){ctx.refuse?.();return;}}catch{ctx.refuse?.();return;}if(!live(node))return;stopSpeech();v.activeRoute=route;ctx.render?.();document.querySelector('#sb-heading')?.focus();});
}
const p=t=>`<p data-sb-read>${esc(t)}</p>`;
function bracket(g,type){if(!g)return '';return g.x1===g.x2?`<circle data-sb-zero="${type}" class="sb-${type}" cx="${g.x1}" cy="${g.y}" r="4"/>`:`<g class="sb-${type}"><line data-sb-bracket="${type}" x1="${g.x1}" x2="${g.x2}" y1="${g.y}" y2="${g.y}"/><path d="M${g.x1} ${g.y-6}v12M${g.x2} ${g.y-6}v12"/></g>`;}
function diagram(m,g,reference){
 const origin=g.origin.x,end=g.end.x,unloadedEnd=g.unloadedEnd.x;
 const coil=[[origin,65],[origin+9,65]];const span=end-origin-18;for(let i=0;i<=22;i++)coil.push([origin+9+span*i/22,i===0||i===22?65:i%2?48:82]);coil.push([end,65]);
 return `<figure class="sb-figure"><svg data-sb-diagram viewBox="0 0 600 240" role="img" aria-label="Schematic spring and fixed centimeter ruler. Current length ${m.length} centimeters; starting unloaded length ${m.startLength} centimeters."><path class="sb-anchor" d="M34 37V94M23 39l11 10M23 57l11 10M23 75l11 10"/><polyline data-sb-coil points="${coil.map(a=>a.join(',')).join(' ')}"/><line data-sb-original x1="${unloadedEnd}" x2="${unloadedEnd}" y1="33" y2="198"/><text x="${unloadedEnd}" y="24" text-anchor="middle">Starting end</text>${bracket(g.proposal,'proposal')}${g.proposal?'<text x="44" y="125">Your extension mark</text>':''}${reference?bracket(g.reference,'reference')+'<text x="44" y="165">Reference extension</text>':''}<line class="sb-ruler" x1="44" x2="512" y1="211" y2="211"/>${Array.from({length:19},(_,i)=>`<path class="sb-tick" d="M${44+i*26} 205v${i%2?6:10}"/>${i%2?'':`<text x="${44+i*26}" y="232" text-anchor="middle">${i}</text>`}`).join('')}<text x="548" y="232">cm</text></svg><figcaption>Schematic spring, settled length. Marks show lengths, not force arrows.</figcaption></figure>`;
}
function readouts(m){return `<div class="sb-readouts" data-sb-read><p>Starting unloaded length: <strong>${m.startLength} cm</strong>.</p><p>Current length: <strong>${m.length} cm</strong>.</p><p>Pull now: <strong>${m.pullNow} N</strong>.</p><p>Test pull: <strong>${m.testForce} N</strong>.</p></div>`;}
function support(m,c){return `<section class="sb-reference" data-sb-reference>${p(springCopy.referenceFormula)}${p(`Reference extension: ${m.length} − ${m.startLength} = ${m.extension} cm, measured from the starting unloaded end.`)}${m.phase==='released'?p(m.extension===0?`With no pull now, the length is ${m.startLength} cm, the same as its starting length, in this model.`:springCopy.retained):''}${p(c.note)}${p(springCopy.nonlinear)}<details><summary>Numbers and units</summary>${p(c.unitsCopy)}${p(springCopy.numbersShared)}</details></section>`;}
function trial(v,m,c){
 const state=m.phase==='fresh'?'Fresh matching spring':m.testForce===0?(m.phase==='loaded'?'Zero-pull reading':'Zero-pull test finished'):(m.phase==='loaded'?'Pull applied':'Pull removed');
 return `<label class="sb-case">Spring model<select data-sb-case>${springCases.map(s=>`<option value="${s.id}"${s.id===v.id?' selected':''}>${s.id} · ${esc(s.title)}</option>`).join('')}</select></label><h2 data-sb-read>${esc(state)}</h2>${p(springCopy.request)}<div class="sb-workbench"><div>${diagram(m,springGeometry(v.id,v.cases.get(v.id)),v.reference)}${readouts(m)}${m.testForce===0&&m.phase!=='fresh'?p(springCopy.zeroHelper):''}</div><section class="sb-tools" aria-label="Spring and mark controls"><label>Test pull<select data-sb-force${m.canSetForce?'':' disabled'}>${c.forces.map(f=>`<option value="${f}"${f===m.testForce?' selected':''}>${f} N</option>`).join('')}</select></label>${m.phase==='fresh'?button('apply','Apply this pull',!m.canApply,true):m.phase==='loaded'?button('release','Remove the pull',!m.canRelease,true):''}${m.phase==='loaded'?p(springCopy.loadedRestriction):m.phase==='released'?p(springCopy.releasedRestriction):''}${p(m.mark===null?springCopy.noMark:`Your extension mark: ${m.mark} cm.`)}<div class="sb-actions">${button('add','Add an extension mark',!m.canAdd)}${button('decrease','Decrease mark by 0.5 cm',!m.canDecrease)}${button('increase','Increase mark by 0.5 cm',!m.canIncrease)}${button('clear','Clear mark',!m.canClear)}${button('undo','Undo mark change',!m.canUndo)}</div>${p(springCopy.markBounds)}</section></div><div class="sb-actions">${button(v.reference?'hide':'compare',v.reference?'Hide reference':'Compare extension')}${button('plots','Show reading plots')}${button('example','Show a separate example')}</div>${v.reference?support(m,c):''}<div class="sb-fresh">${p(springCopy.resetNote)}${button('fresh','Fresh matching spring',!m.canFresh,m.phase==='released')}${!m.canFresh?p(springCopy.alreadyFresh):''}</div>`;
}
function plotPoint(row,kind){return `<g data-sb-point="${kind}"${kind==='loading'?` data-force="${row.force}"`:''} transform="translate(${row.x} ${row.y})">${kind==='loading'?'<circle r="6"/>':kind==='release'?'<rect x="-7" y="-7" width="14" height="14"/>':'<path d="M0 -9L8 6H-8Z"/>'}</g>`;}
function plots(v,m,c){const g=springPlot(v.id,v.cases.get(v.id),v.axis);return `<h2 data-sb-read>${esc(c.title)} · model reading plots</h2>${p('Compare the model’s length and extension at each pull. These tables and points show the model answers.')}<div class="sb-actions" role="group" aria-label="Vertical quantity">${['length','extension'].map(a=>`<button type="button" data-sb-axis="${a}" aria-pressed="${v.axis===a}">${a==='length'?'Length':'Extension from starting length'}</button>`).join('')}</div><h3 data-sb-read>${v.axis==='length'?'Length (cm)':'Extension from starting length (cm)'}</h3><svg data-sb-plot viewBox="0 0 600 400" role="img" aria-label="Applied pull in newtons across; ${v.axis} in centimeters up. Model values are in the table below.">${[0,4,8,12,16,20].map(n=>`<path class="sb-grid" d="M80 ${330-13*n}H520"/><text x="67" y="${335-13*n}" text-anchor="end">${n}</text>`).join('')}${[0,1,2,3,4].map(n=>`<path class="sb-grid" d="M${80+110*n} 70V330"/><text x="${80+110*n}" y="353" text-anchor="middle">${n}</text>`).join('')}<path class="sb-axes" d="M80 70V330H520"/><polyline class="sb-loading-line" points="${g.loading.map(r=>`${r.x},${r.y}`).join(' ')}"/>${g.loading.map(r=>plotPoint(r,'loading')).join('')}${g.release?plotPoint(g.release,'release'):''}${g.proposal?plotPoint(g.proposal,'proposal'):''}<text x="300" y="387" text-anchor="middle">Applied pull (N)</text></svg>${p(springCopy.plotGuide)}<p class="sb-legend" data-sb-read><span><span aria-hidden="true">●</span> Filled circles: model loading readings.</span> <span><span aria-hidden="true">□</span> Hollow square: this test after removing the pull.</span> <span><span aria-hidden="true">▲</span> Blue triangle: your mark at the pull now.</span></p><table data-sb-table><caption>Model loading readings</caption><thead><tr><th>Applied pull (N)</th><th>Length (cm)</th><th>Extension (cm)</th></tr></thead><tbody>${g.loading.map(r=>`<tr data-force="${r.force}"><td>${r.force}</td><td>${r.length}</td><td>${r.extension}</td></tr>`).join('')}${g.release?`<tr data-sb-released><th>After removing this test pull: 0 N</th><td>${g.release.length}</td><td>${g.release.extension}</td></tr>`:''}</tbody></table>${readouts(m)}${p(m.mark===null?'No extension mark yet.':`Your extension mark: ${m.mark} cm, at the pull now.`)}${support(m,c)}<div class="sb-actions">${button('trial','Back to trial')}${button('example','Show a separate example')}</div>`;}
function example(v){const e=springExample(v.frame);return `<h2 data-sb-read>A separate example</h2>${p(`Picture ${v.frame+1} of 5. ${e.caption}`)}${diagram(e.model,e.geometry,e.showReference)}${readouts(e.model)}${e.model.mark===null?'':p(`Example extension mark: ${e.model.mark} cm.`)}<div class="sb-actions">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===4)}${button('back',v.caller==='plots'?'Back to plots':'Back to trial')}</div>`;}
export function springBenchPage(book,owner){const v=visit(book,owner,true);if(!v)return '';v.generation++;const m=springModel(v.id,v.cases.get(v.id)),c=springCases.find(c=>c.id===v.id);if(!m||!c)return '';return `<section class="sb-page" data-sb-root data-sb-view="${v.screen}" data-sb-selected-case="${v.id}"><header><button type="button" data-sb-parent>Motion and Evidence</button><h1 id="sb-heading" tabindex="-1">Spring Bench</h1>${v.screen==='trial'?p(springCopy.intro):''}</header><div class="sb-mat">${v.screen==='example'?example(v):v.screen==='plots'?plots(v,m,c):trial(v,m,c)}<div class="sb-actions">${button('read',v.screen==='example'?'Read this example':v.screen==='plots'?'Read these plots':'Read this spring').replace('data-sb-action="read"','data-sb-action="read" data-speak=""')}</div>${v.screen==='trial'?`${p(springCopy.key)}${p(springCopy.modelNote)}${p(springCopy.units)}`:''}<details><summary>Talk together</summary>${p(springCopy.talkTogether)}</details><details><summary>For grown-ups</summary>${p(springCopy.grownUp)}</details>${p(springCopy.visit)}</div></section>`;}
function narration(root){function read(n){if(n.nodeType===3)return n.textContent+' ';if(n.nodeType!==1)return '';if(n.matches('select[data-sb-case]'))return (n.selectedOptions[0]?.textContent||'')+'. ';if(n.matches('svg,select,button,[hidden],[aria-hidden="true"],.speech-controls,drawn-howto'))return '';if(n.tagName==='DETAILS'&&!n.open)return '';return [...n.childNodes].map(read).join(' ');}return read(root).replace(/(\d+(?:\.\d+)?)\s*N\/cm\b/g,(_,n)=>`${n} newton${Number(n)===1?'':'s'} per centimeter`).replace(/(\d+(?:\.\d+)?)\s*cm\/N\b/g,(_,n)=>`${n} centimeter${Number(n)===1?'':'s'} per newton`).replace(/\bN\/cm\b/g,'newtons per centimeter').replace(/\bcm\/N\b/g,'centimeters per newton').replace(/(\d+(?:\.\d+)?)\s*N\b/g,(_,n)=>`${n} newton${Number(n)===1?'':'s'}`).replace(/\(N\)/g,'(newtons)').replace(/\s+/g,' ').trim();}
export function bindSpringBench(book,ctx={}){
 const owner=ctx.explorerId?.(),v=visit(book,owner),root=document.querySelector('[data-sb-root]');if(!v||!root)return;
 const route=location.hash,generation=v.generation,work=v.cases.get(v.id),signature=bytes(work),id=v.id,screen=v.screen,frame=v.frame,axis=v.axis,reference=v.reference,caller=v.caller;v.root=root;
 const valid=()=>visit(book,owner)===v&&v.root===root&&v.generation===generation&&v.id===id&&v.cases.get(id)===work&&bytes(work)===signature&&v.screen===screen&&v.frame===frame&&v.axis===axis&&v.reference===reference&&v.caller===caller&&ctx.notebook?.()===book&&ctx.explorerId?.()===owner&&ctx.isActive?.()===true&&location.hash===route&&springBenchActive(book,owner,route)&&document.querySelector('[data-sb-root]')===root;
 const live=bindingGuard(root,valid,stopSpeech);
 for(const node of root.querySelectorAll('button,input,select,a,details,summary')){if(node.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','input','change','keydown'])node.addEventListener(type,e=>{if(!live(node)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});}
 const focus=selector=>{const r=document.querySelector('[data-sb-root]'),n=r?.querySelector(selector),target=n&&!n.disabled?n:r?.querySelector('#sb-heading');target?.focus({preventScroll:true});if(target){const b=target.getBoundingClientRect();if(b.top<0||b.bottom>innerHeight)target.scrollIntoView({block:'nearest'});}};
 const redraw=selector=>{stopSpeech();ctx.render?.();focus(selector||'#sb-heading');};
 root.querySelector('[data-sb-case]')?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||n.value===id||!v.cases.has(n.value))return;v.id=n.value;v.reference=false;redraw('[data-sb-case]');});
 root.querySelector('[data-sb-force]')?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||!/^(0|[1-4])$/.test(n.value))return;const next=changeSpring(id,work,'force',Number(n.value));if(!next)return;v.cases.set(id,next);v.reference=false;redraw('[data-sb-force]');});
 root.querySelector('[data-sb-parent]')?.addEventListener('click',e=>{if(!live(e.currentTarget))return;stopSpeech();v.activeRoute=null;v.root=null;ctx.render?.();document.querySelector('[data-sb-entry]')?.focus();});
 for(const n of root.querySelectorAll('[data-sb-axis]'))n.addEventListener('click',()=>{if(!live(n)||n.dataset.sbAxis===axis||!['length','extension'].includes(n.dataset.sbAxis))return;v.axis=n.dataset.sbAxis;redraw(`[data-sb-axis="${v.axis}"]`);});
 for(const n of root.querySelectorAll('[data-sb-action]'))n.addEventListener('click',()=>{if(!live(n))return;const action=n.dataset.sbAction;if(action==='read'){n.dataset.speak=narration(root);return;}if(['apply','release','fresh','add','decrease','increase','clear','undo'].includes(action)){const next=changeSpring(id,work,action);if(!next)return;v.cases.set(id,next);v.reference=false;const m=springModel(id,next),target=action==='apply'?'release':action==='release'?'fresh':action==='add'?'increase':action==='clear'?'undo':action==='undo'?(m.mark===null?'add':m.canIncrease?'increase':'decrease'):action==='increase'&&!m.canIncrease?'decrease':action==='decrease'&&!m.canDecrease?'increase':action;redraw(action==='fresh'?'[data-sb-force]':`[data-sb-action="${target}"]`);return;}
 if(action==='compare'||action==='hide'){v.reference=action==='compare';redraw(`[data-sb-action="${v.reference?'hide':'compare'}"]`);}else if(action==='plots'){v.screen='plots';redraw();}else if(action==='trial'){v.screen='trial';redraw('[data-sb-action="plots"]');}else if(action==='example'){v.caller=screen;v.screen='example';v.frame=0;redraw();}else if(action==='back'){v.screen=caller;redraw('[data-sb-action="example"]');}else if(action==='previous'||action==='next'){const next=frame+(action==='next'?1:-1);if(next<0||next>4)return;v.frame=next;redraw(`[data-sb-action="${next===4?'previous':next===0?'next':action}"]`);}});
}
